import{_ as t,a0 as o,w as r,s as d,I as a,x as n,a1 as p,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 Traefik 引導 Kubernetes 流量 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Traefik 引導 Kubernetes 流量 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Traefik 引導 Kubernetes 流量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Traefik 引導 Kubernetes 流量 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200311 Directing Kubernetes traffic with Traefik","title":"使用 Traefik 引導 Kubernetes 流量","tag":"202004","desc":""},"relativePath":"202004/20200311 Directing Kubernetes traffic with Traefik.md","filePath":"[post].md"}'),c={name:"202004/20200311 Directing Kubernetes traffic with Traefik.md"};function g(h,s,u,m,k,b){const e=o("Link");return r(),d("div",null,[s[30]||(s[30]=a("h1",{id:"使用-traefik-引導-kubernetes-流量",tabindex:"-1"},[n("使用 Traefik 引導 Kubernetes 流量 "),a("a",{class:"header-anchor",href:"#使用-traefik-引導-kubernetes-流量","aria-label":"Permalink to “使用 Traefik 引導 Kubernetes 流量”"},"​")],-1)),s[31]||(s[31]=a("blockquote",null,[a("p",null,"將流量引入 Kubernetes 樹莓派集羣的分步指南。")],-1)),s[32]||(s[32]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/browser_web_internet_website.png?itok=g5B_Bw62",alt:"Digital creative of a browser on the internet",title:"Digital creative of a browser on the internet"})],-1)),s[33]||(s[33]=a("p",null,"在本文中，我們將部署幾個簡單的網站，並學習如何使用 Traefik 將來自外部世界的流量引入到我們的集羣中。之後，我們還將學習如何刪除 Kubernetes 資源。讓我們開始吧！",-1)),a("ul",null,[a("li",null,[p(e,{href:"https://img.linux.net.cn/static/video/Ingressing%20with%20k3s-QcC-5fRhsM8.mp4"},{default:i(()=>[...s[0]||(s[0]=[n("video",-1)])]),_:1})])]),s[34]||(s[34]=a("h3",{id:"準備",tabindex:"-1"},[n("準備 "),a("a",{class:"header-anchor",href:"#準備","aria-label":"Permalink to “準備”"},"​")],-1)),a("p",null,[s[2]||(s[2]=n("要繼續閲讀本文，你只需要我們在上一篇文章中構建的 ",-1)),p(e,{href:"https://linux.cn/article-12049-1.html"},{default:i(()=>[...s[1]||(s[1]=[n("k3s 樹莓派集羣",-1)])]),_:1}),s[3]||(s[3]=n("。由於你的集羣將從網絡上拉取鏡像，因此該集羣需要能夠訪問互聯網。",-1))]),a("p",null,[s[5]||(s[5]=n("出於解釋目的，本文將顯示一些配置文件和示例 HTML 文件。所有示例文件都可以在",-1)),p(e,{href:"https://gitlab.com/carpie/ingressing_with_k3s/-/archive/master/ingressing_with_k3s-master.zip"},{default:i(()=>[...s[4]||(s[4]=[n("此處",-1)])]),_:1}),s[6]||(s[6]=n("下載。",-1))]),s[35]||(s[35]=a("h3",{id:"部署一個簡單的網站",tabindex:"-1"},[n("部署一個簡單的網站 "),a("a",{class:"header-anchor",href:"#部署一個簡單的網站","aria-label":"Permalink to “部署一個簡單的網站”"},"​")],-1)),s[36]||(s[36]=a("p",null,[n("之前，我們使用 "),a("code",null,"kubectl"),n(" 進行了直接部署。但是，這不是典型的部署方法。一般情況都會使用 YAML 配置文件，這也是我們要在本文中使用的配置文件。我們將從頂部開始，並以自頂向下的方式創建該配置文件。")],-1)),s[37]||(s[37]=a("h3",{id:"部署配置",tabindex:"-1"},[n("部署配置 "),a("a",{class:"header-anchor",href:"#部署配置","aria-label":"Permalink to “部署配置”"},"​")],-1)),a("p",null,[s[9]||(s[9]=n("首先是部署配置。配置如下所示，並在下面進行説明。我通常以 ",-1)),p(e,{href:"https://kubernetes.io/docs/"},{default:i(()=>[...s[7]||(s[7]=[n("Kubernetes 文檔",-1)])]),_:1}),s[10]||(s[10]=n("中的示例為起點，然後根據需要對其進行修改。例如，下面的配置是複製了",-1)),p(e,{href:"https://kubernetes.io/docs/concepts/workloads/controllers/deployment/#creating-a-deployment"},{default:i(()=>[...s[8]||(s[8]=[n("部署文檔",-1)])]),_:1}),s[11]||(s[11]=n("中的示例後修改的。",-1))]),s[38]||(s[38]=l(`<p>創建一個文件 <code>mysite.yaml</code>，其內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mysite-nginx</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: mysite-nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  replicas: 1</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    matchLabels:</span></span>
<span class="line"><span>      app: mysite-nginx</span></span>
<span class="line"><span>  template:</span></span>
<span class="line"><span>    metadata:</span></span>
<span class="line"><span>      labels:</span></span>
<span class="line"><span>        app: mysite-nginx</span></span>
<span class="line"><span>    spec:</span></span>
<span class="line"><span>      containers:</span></span>
<span class="line"><span>      - name: nginx</span></span>
<span class="line"><span>        image: nginx</span></span>
<span class="line"><span>        ports:</span></span>
<span class="line"><span>        - containerPort: 80</span></span></code></pre></div><p>其中大部分是樣板。重要的部分，我們會將該部署命名為 <code>mysite-nginx</code>，併為其加上同名的 <code>app</code> 標籤。我們指定了一個<ruby>副本<rt>replica</rt></ruby>，這意味着將只創建一個 Pod。我們還指定了一個容器，我們將其命名為 <code>nginx</code>。我們將<ruby>鏡像<rt>image</rt></ruby>指定為 <code>nginx</code>。這意味着在部署時，k3s 將從 DockerHub 下載 <code>nginx</code> 鏡像並從中創建一個 Pod。最後，我們指定了<ruby>容器端口<rt>containerPort</rt></ruby>為 <code>80</code>，這隻意味着在容器內部 Pod 會監聽 <code>80</code> 端口。</p><p>我在上面強調了“在容器內部”，因為這是一個重要的區別。由於我們是按容器配置的，因此只能在容器內部訪問它，並且進一步將其限制為內部網絡。這對於允許多個容器在同一容器端口上監聽所是必要的。換句話説，通過這種配置，其他一些 Pod 也可以在其容器端口 80 上偵聽，並且不會與此容器衝突。為了提供對該 Pod 的正式訪問權限，我們需要一個<ruby>服務<rt>service</rt></ruby>配置。</p><h3 id="服務配置" tabindex="-1">服務配置 <a class="header-anchor" href="#服務配置" aria-label="Permalink to “服務配置”">​</a></h3><p>在 Kubernetes 中，<ruby>服務<rt>service</rt></ruby>是一種抽象。它提供了一種訪問 Pod 或 Pod 集合的方法。當連接到服務時，服務會路由到單個 Pod，或者如果定義了多個 Pod 副本，會通過負載均衡路由到多個 Pod。</p><p>可以在同一配置文件中指定該服務，這就是我們將在此處要做的。用 <code>---</code> 分隔配置區域，將以下內容添加到 <code>mysite.yaml</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Service</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mysite-nginx-service</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    app: mysite-nginx</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>    - protocol: TCP</span></span>
<span class="line"><span>      port: 80</span></span></code></pre></div><p>在此配置中，我們將服務命名為 <code>mysite-nginx-service</code>。我們提供了一個<ruby>選擇器<rt>selector</rt></ruby>：<code>app: mysite-nginx</code>。這是服務選擇其路由到的應用程序容器的方式。請記住，我們為容器提供了 <code>app</code> 標籤：<code>mysite-nginx</code> 。這就是服務用來查找我們的容器的方式。最後，我們指定服務協議為 <code>TCP</code>，在端口 <code>80</code> 上監聽。</p><h3 id="入口配置" tabindex="-1">入口配置 <a class="header-anchor" href="#入口配置" aria-label="Permalink to “入口配置”">​</a></h3><p><ruby>入口<rt>Ingress</rt></ruby>配置指定了如何將流量從集羣外部傳遞到集羣內部的服務。請記住，k3s 預先配置了 Traefik 作為入口控制器。因此，我們將編寫特定於 Traefik 的入口配置。將以下內容添加到 <code>mysite.yaml</code> 中（不要忘了用 <code>---</code> 分隔）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: networking.k8s.io/v1beta1</span></span>
<span class="line"><span>kind: Ingress</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mysite-nginx-ingress</span></span>
<span class="line"><span>  annotations:</span></span>
<span class="line"><span>    kubernetes.io/ingress.class: &quot;traefik&quot;</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  rules:</span></span>
<span class="line"><span>  - http:</span></span>
<span class="line"><span>      paths:</span></span>
<span class="line"><span>      - path: /</span></span>
<span class="line"><span>        backend:</span></span>
<span class="line"><span>          serviceName: mysite-nginx-service</span></span>
<span class="line"><span>          servicePort: 80</span></span></code></pre></div><p>在此配置中，我們將入口記錄命名為 <code>mysite-nginx-ingress</code>。我們告訴 Kubernetes，我們希望 <code>traefik</code> 成為我們的入口控制器，再加上 <code>kubernetes.io/ingress.class</code> 的註解。</p><p>在<ruby>規則<rt>rules</rt></ruby>部分中，我們基本上是説，當 <code>http</code> 流量進入時，並且 <code>path</code> 匹配 <code>/</code>（或其下的任何內容），將其路由到由 <code>serviceName mysite-nginx-service</code> 指定的<ruby>後端<rt>backend</rt></ruby>服務中，並將其路由到 <code>servicePort 80</code>。這會將傳入的 HTTP 流量連接到我們之前定義的服務。</p><h3 id="需要部署的東西" tabindex="-1">需要部署的東西 <a class="header-anchor" href="#需要部署的東西" aria-label="Permalink to “需要部署的東西”">​</a></h3><p>就配置而言，就是這樣了。如果我們現在部署，我們將獲得默認的 nginx 頁面，但這不是我們想要的。讓我們創建一些簡單但可自定義的部署方式。創建具有以下內容的文件 <code>index.html</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;&lt;title&gt;K3S!&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;style&gt;</span></span>
<span class="line"><span>    html {</span></span>
<span class="line"><span>      font-size: 62.5%;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    body {</span></span>
<span class="line"><span>      font-family: sans-serif;</span></span>
<span class="line"><span>      background-color: midnightblue;</span></span>
<span class="line"><span>      color: white;</span></span>
<span class="line"><span>      display: flex;</span></span>
<span class="line"><span>      flex-direction: column;</span></span>
<span class="line"><span>      justify-content: center;</span></span>
<span class="line"><span>      height: 100vh;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    div {</span></span>
<span class="line"><span>      text-align: center;</span></span>
<span class="line"><span>      font-size: 8rem;</span></span>
<span class="line"><span>      text-shadow: 3px 3px 4px dimgrey;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  &lt;/style&gt;</span></span>
<span class="line"><span>&lt;/head&gt;</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>  &lt;div&gt;Hello from K3S!&lt;/div&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>我們尚未介紹 Kubernetes 中的存儲機制，因此在這裏我們偷懶一下，僅將該文件存儲在 Kubernetes 配置映射中。這不是我們推薦的部署網站的方式，但對於我們的目的來説是可行的。運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl create configmap mysite-html --from-file index.html</span></span></code></pre></div><p>該命令從本地文件 <code>index.html</code> 創建名為 <code>mysite-html</code> 的<ruby>配置映射<rt>configmap</rt></ruby>資源。這實際上是在 Kubernetes 資源中存儲一個文件（或一組文件），我們可以在配置中調出該文件。它通常用於存儲配置文件（因此而得名），我們在這裏稍加濫用。在以後的文章中，我們將討論 Kubernetes 中適當的存儲解決方案。</p><p>創建配置映射後，讓我們將其掛載在我們的 <code>nginx</code> 容器中。我們分兩個步驟進行。首先，我們需要指定一個<ruby>卷<rt>volume</rt></ruby>來調出配置映射。然後我們需要將該卷掛載到 <code>nginx</code> 容器中。通過在 <code>mysite.yaml</code> 中的 <code>container</code> 後面的 <code>spec</code> 標籤下添加以下內容來完成第一步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>      volumes:</span></span>
<span class="line"><span>      - name: html-volume</span></span>
<span class="line"><span>        configMap:</span></span>
<span class="line"><span>          name: mysite-html</span></span></code></pre></div><p>這告訴 Kubernetes 我們要定義一個名為 <code>html-volume</code> 的卷，並且該卷應包含名為 <code>html-volume</code>（我們在上一步中創建的）的配置映射的內容。</p><p>接下來，在 <code>nginx</code> 容器規範中的<ruby>端口<rt>ports</rt></ruby>下方，添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>        volumeMounts:</span></span>
<span class="line"><span>        - name: html-volume</span></span>
<span class="line"><span>          mountPath: /usr/share/nginx/html</span></span></code></pre></div><p>這告訴 Kubernetes，對於 <code>nginx</code> 容器，我們想在容器中的 <code>/usr/share/nginx/html</code> 路徑上掛載名為 <code>html-volume</code> 的卷。 為什麼要使用 <code>/usr/share/nginx/html</code>？那個位置就是 <code>nginx</code> 鏡像提供 HTML 服務的地方。通過在該路徑上掛載卷，我們用該卷內容替換了默認內容。</p><p>作為參考，配置文件的 <code>deployment</code> 部分現在應如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mysite-nginx</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: mysite-nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  replicas: 1</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    matchLabels:</span></span>
<span class="line"><span>      app: mysite-nginx</span></span>
<span class="line"><span>  template:</span></span>
<span class="line"><span>    metadata:</span></span>
<span class="line"><span>      labels:</span></span>
<span class="line"><span>        app: mysite-nginx</span></span>
<span class="line"><span>    spec:</span></span>
<span class="line"><span>      containers:</span></span>
<span class="line"><span>      - name: nginx</span></span>
<span class="line"><span>        image: nginx</span></span>
<span class="line"><span>        ports:</span></span>
<span class="line"><span>        - containerPort: 80</span></span>
<span class="line"><span>        volumeMounts:</span></span>
<span class="line"><span>        - name: html-volume</span></span>
<span class="line"><span>          mountPath: /usr/share/nginx/html</span></span>
<span class="line"><span>      volumes:</span></span>
<span class="line"><span>      - name: html-volume</span></span>
<span class="line"><span>        configMap:</span></span>
<span class="line"><span>          name: mysite-html</span></span></code></pre></div><h3 id="部署它" tabindex="-1">部署它！ <a class="header-anchor" href="#部署它" aria-label="Permalink to “部署它！”">​</a></h3><p>現在我們準備部署！ 我們可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl apply -f mysite.yaml</span></span></code></pre></div><p>你應該看到類似於以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deployment.apps/mysite-nginx created</span></span>
<span class="line"><span>service/mysite-nginx-service created</span></span>
<span class="line"><span>ingress.networking.k8s.io/mysite-nginx-ingress created</span></span></code></pre></div><p>這意味着 Kubernetes 為我們指定的三個配置分別創建了資源。使用以下方法檢查 Pod 的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl get pods</span></span></code></pre></div><p>如果看到狀態為 <code>ContainerCreating</code>，請給它一些時間並再次運行 <code>kubectl get pods</code>。通常，第一次會花一些時間，因為 k3s 必須下載 <code>nginx</code> 鏡像來創建 Pod。一段時間後，你應該看到 <code>Running</code> 的狀態。</p><h3 id="嘗試一下" tabindex="-1">嘗試一下！ <a class="header-anchor" href="#嘗試一下" aria-label="Permalink to “嘗試一下！”">​</a></h3><p>Pod 運行之後，就該嘗試了。打開瀏覽器，然後在地址欄中輸入 <code>kmaster</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/mysite.jpg" alt=""></p><p>恭喜你！你已經在 k3s 集羣上部署了一個網站！</p><h3 id="另一個" tabindex="-1">另一個 <a class="header-anchor" href="#另一個" aria-label="Permalink to “另一個”">​</a></h3><p>因此，現在我們有了一個運行單個網站的整個 k3s 集羣。但是我們可以有更多的網站！如果我們要在同一集羣中提供另一個網站怎麼辦？讓我們看看如何做到這一點。</p><p>同樣，我們需要部署一些東西。碰巧我的狗有一條她想讓全世界都知道的信息，她想了好久了。因此，我專門為她製作了一些 HTML（可從示例 zip 文件中獲得）。同樣，我們將使用配置映射的技巧來託管這些 HTML。這次我們將把整個目錄（<code>html</code> 目錄）放到配置映射中，但是調用是相同的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl create configmap mydog-html --from-file html</span></span></code></pre></div><p>現在，我們需要為此站點創建一個配置文件。它幾乎與用於 <code>mysite.yaml</code> 的完全相同，因此首先將 <code>mysite.yaml</code> 複製為 <code>mydog.yaml</code>。現在將 <code>mydog.yaml</code> 修改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mydog-nginx</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: mydog-nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  replicas: 1</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    matchLabels:</span></span>
<span class="line"><span>      app: mydog-nginx</span></span>
<span class="line"><span>  template:</span></span>
<span class="line"><span>    metadata:</span></span>
<span class="line"><span>      labels:</span></span>
<span class="line"><span>        app: mydog-nginx</span></span>
<span class="line"><span>    spec:</span></span>
<span class="line"><span>      containers:</span></span>
<span class="line"><span>      - name: nginx</span></span>
<span class="line"><span>        image: nginx</span></span>
<span class="line"><span>        ports:</span></span>
<span class="line"><span>        - containerPort: 80</span></span>
<span class="line"><span>        volumeMounts:</span></span>
<span class="line"><span>        - name: html-volume</span></span>
<span class="line"><span>          mountPath: /usr/share/nginx/html</span></span>
<span class="line"><span>      volumes:</span></span>
<span class="line"><span>      - name: html-volume</span></span>
<span class="line"><span>        configMap:</span></span>
<span class="line"><span>          name: mydog-html</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Service</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mydog-nginx-service</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    app: mydog-nginx</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>    - protocol: TCP</span></span>
<span class="line"><span>      port: 80</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: networking.k8s.io/v1beta1</span></span>
<span class="line"><span>kind: Ingress</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: mydog-nginx-ingress</span></span>
<span class="line"><span>  annotations:</span></span>
<span class="line"><span>    kubernetes.io/ingress.class: &quot;traefik&quot;</span></span>
<span class="line"><span>    traefik.frontend.rule.type: PathPrefixStrip</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  rules:</span></span>
<span class="line"><span>  - http:</span></span>
<span class="line"><span>      paths:</span></span>
<span class="line"><span>      - path: /mydog</span></span>
<span class="line"><span>        backend:</span></span>
<span class="line"><span>          serviceName: mydog-nginx-service</span></span>
<span class="line"><span>          servicePort: 80</span></span></code></pre></div><p>我們只需進行搜索並將 <code>mysite</code> 替換為 <code>mydog</code>即可完成大多數修改。其他兩個修改在入口部分中。我們將 <code>path</code> 更改為 <code>/mydog</code>，並添加了一個註解 <code>traefik.frontend.rule.type: PathPrefixStrip</code>。</p><p><code>/mydog</code> 路徑的規範指示 Traefik 將以 <code>/mydog</code> 路徑開頭的所有傳入請求路由到 <code>mydog-nginx-service</code>。任何其他路徑將繼續路由到 <code>mysite-nginx-service</code>。</p><p>新的註解 <code>PathPrefixStrip</code> 告訴 Traefik 在將請求發送到 <code>mydog-nginx-service</code> 之前先去除前綴 <code>/mydog</code>。我們這樣做是因為 <code>mydog-nginx</code> 應用程序不需要前綴。這意味着我們可以簡單地通過更改入口記錄中的前綴來更改掛載的服務的位置。</p><p>現在我們可以像以前一樣進行部署：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl apply -f mydog.yaml</span></span></code></pre></div>`,51)),a("p",null,[s[13]||(s[13]=n("現在，我的狗的消息應該可以在 ",-1)),p(e,{href:"http://kmaster/mydog/"},{default:i(()=>[...s[12]||(s[12]=[n("http://kmaster/mydog/",-1)])]),_:1}),s[14]||(s[14]=n(" 上找到。",-1))]),s[39]||(s[39]=l(`<p><img src="https://opensource.com/sites/default/files/uploads/mydog.jpg" alt=""></p><p>呼！消息發出去了！也許今晚我們都可以睡一覺。</p><p>因此，現在，我們有了一個 k3s 集羣，該集羣託管了兩個網站，Traefik 根據路徑名決定將請求傳遞給哪個服務！但是，不僅限於基於路徑的路由，我們也可以使用基於主機名的路由，我們將在以後的文章中進行探討。</p><p>另外，我們剛剛託管的網站是標準的未加密 HTML 網站，而如今的所有內容都使用 SSL/TLS 加密。在我們的下一篇文章中，我們將為 k3s 集羣添加支持以託管 SSL/TLS HTTPS 站點！</p><h3 id="清理" tabindex="-1">清理 <a class="header-anchor" href="#清理" aria-label="Permalink to “清理”">​</a></h3><p>在開始之前，由於本文主要涉及的是示例站點，因此我想向你展示如何刪除內容，以防萬一你不希望將這些示例丟在集羣中。</p><p>對於大多數配置，只需使用與部署時使用的相同配置文件運行 <code>delete</code> 命令即可撤消配置。因此，讓我們同時清理 <code>mysite</code> 和 <code>mydog</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl delete -f mysite.yaml</span></span>
<span class="line"><span>kubectl delete -f mydog.yaml</span></span></code></pre></div><p>由於我們是手動創建配置映射的，因此我們也需要手動刪除它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl delete configmap mysite-html</span></span>
<span class="line"><span>kubectl delete configmap mydog-html</span></span></code></pre></div><p>現在，如果我們執行 <code>kubectl get pods</code>，我們應該看到我們的 nginx Pod 不存在了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pods</span></span>
<span class="line"><span>No resources found in default namespace.</span></span></code></pre></div><p>一切都清理了。</p><p>請在下面的評論中告訴我你對這個項目有什麼想法。</p><hr>`,15)),a("p",null,[s[16]||(s[16]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/20/3/kubernetes-traefik"},{default:i(()=>[...s[15]||(s[15]=[n("https://opensource.com/article/20/3/kubernetes-traefik",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/carpie"},{default:i(()=>[...s[17]||(s[17]=[n("Lee Carpenter",-1)])]),_:1}),s[22]||(s[22]=n(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[18]||(s[18]=[n("lujun9972",-1)])]),_:1}),s[23]||(s[23]=n(" 譯者：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[19]||(s[19]=[n("wxy",-1)])]),_:1}),s[24]||(s[24]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[20]||(s[20]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[26]||(s[26]=[n("Linux中國",-1)])]),_:1}),s[29]||(s[29]=n(" 榮譽推出",-1))])])}const v=t(c,[["render",g]]);export{x as __pageData,v as default};
